`timescale 1ns/1ps
module tb;
  reg d0, d1, d2, d3;
  reg [1:0] sel;
  wire y;

  mux4to1 dut (.d0(d0), .d1(d1), .d2(d2), .d3(d3), .sel(sel), .y(y));

  initial begin
    #10000 $display("##TIMEOUT");
    $finish;
  end

  initial begin
    d0=1'b0; d1=1'b1; d2=1'b0; d3=1'b1; sel=2'b00; #1;
    if (y===1'b0) $display("##TEST T1 PASS exp=0 got=%0d", y); else $display("##TEST T1 FAIL exp=0 got=%0d", y);

    sel=2'b01; #1;
    if (y===1'b1) $display("##TEST T2 PASS exp=1 got=%0d", y); else $display("##TEST T2 FAIL exp=1 got=%0d", y);

    d0=1'b1; d1=1'b0; d2=1'b1; d3=1'b0; sel=2'b10; #1;
    if (y===1'b1) $display("##TEST T3 PASS exp=1 got=%0d", y); else $display("##TEST T3 FAIL exp=1 got=%0d", y);

    sel=2'b11; #1;
    if (y===1'b0) $display("##TEST T4 PASS exp=0 got=%0d", y); else $display("##TEST T4 FAIL exp=0 got=%0d", y);

    d0=1'b0; d1=1'b0; d2=1'b0; d3=1'b0;
    sel=2'b00; #1;
    if (y===1'b0) $display("##TEST T5 PASS exp=0 got=%0d", y); else $display("##TEST T5 FAIL exp=0 got=%0d", y);
    sel=2'b10; #1;
    if (y!==1'b0) $display("##TEST T5 FAIL exp=0 got=%0d", y);

    d0=1'b1; d1=1'b1; d2=1'b1; d3=1'b1;
    sel=2'b01; #1;
    if (y===1'b1) $display("##TEST T6 PASS exp=1 got=%0d", y); else $display("##TEST T6 FAIL exp=1 got=%0d", y);
    sel=2'b11; #1;
    if (y!==1'b1) $display("##TEST T6 FAIL exp=1 got=%0d", y);

    $display("##DONE");
    $finish;
  end
endmodule

reference_sv:
module mux4to1 (
    input  logic d0, d1, d2, d3,
    input  logic [1:0] sel,
    output logic y
);
    always @(*) begin
        case (sel)
            2'b00: y = d0;
            2'b01: y = d1;
            2'b10: y = d2;
            2'b11: y = d3;
        endcase
    end
endmodule
